Lemma disjoint_from_mono : forall W a n n', disjoint_from W a n -> n' <= n -> disjoint_from W a n'.
Proof. induction W as [|[lo hi] W IH]; cbn; intros a n n' H Hn; [exact I|]. destruct H as [H1 H2]. split; [lia| eauto]. Qed.

